/* Inert IUP-only smoke test. No Clumsy, WinDivert, network, or visible windows. */
#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <stdio.h>
#include <wchar.h>
#include <string.h>
#include "iup.h"

static int clicks = 0;
static int on_click(Ihandle* button) { if (!button) return IUP_ERROR; ++clicks; return IUP_DEFAULT; }

#define DECLARE(name, result, arguments) typedef result (*name##_type) arguments; name##_type p##name = NULL
#define RESOLVE(name) do { p##name = (name##_type)GetProcAddress(module, #name); if (!p##name) { failure = #name " missing"; goto cleanup; } } while (0)
#define REQUIRE(condition, label) do { if (!(condition)) { failure = label; goto cleanup; } } while (0)

int wmain(int argc, wchar_t** argv) {
  HMODULE module = NULL;
  Ihandle *label = NULL, *button = NULL, *image = NULL, *box = NULL, *dialog = NULL;
  HDC dc = NULL;
  HBITMAP bitmap = NULL;
  HGDIOBJ previous = NULL;
  HANDLE token = NULL;
  TOKEN_ELEVATION elevation;
  DWORD token_size = 0;
  wchar_t loaded[MAX_PATH];
  const char* failure = NULL;
  int opened = 0, mapped = 0, result = 1;
  unsigned char pixels[16] = {255,0,0,255, 0,255,0,255, 0,0,255,255, 255,255,255,255};
  Ihandle* children[3];
  BITMAPINFO info;
  void* dib = NULL;
  DRAWITEMSTRUCT draw;
  HWND label_hwnd, button_hwnd;
  DECLARE(IupOpen, int, (int*, char***));
  DECLARE(IupClose, void, (void));
  DECLARE(IupVersion, char*, (void));
  DECLARE(IupVersionNumber, int, (void));
  DECLARE(IupImageRGBA, Ihandle*, (int, int, const unsigned char*));
  DECLARE(IupLabel, Ihandle*, (const char*));
  DECLARE(IupButton, Ihandle*, (const char*, const char*));
  DECLARE(IupVboxv, Ihandle*, (Ihandle**));
  DECLARE(IupDialog, Ihandle*, (Ihandle*));
  DECLARE(IupSetAttribute, void, (Ihandle*, const char*, const char*));
  DECLARE(IupSetStrAttribute, void, (Ihandle*, const char*, const char*));
  DECLARE(IupGetAttribute, char*, (Ihandle*, const char*));
  DECLARE(IupSetAttributeHandle, void, (Ihandle*, const char*, Ihandle*));
  DECLARE(IupSetCallback, Icallback, (Ihandle*, const char*, Icallback));
  DECLARE(IupMap, int, (Ihandle*));
  DECLARE(IupUnmap, void, (Ihandle*));
  DECLARE(IupDestroy, void, (Ihandle*));

  REQUIRE(argc == 2 && wcslen(argv[1]) < MAX_PATH, "exact DLL path argument required");
  REQUIRE(OpenProcessToken(GetCurrentProcess(), TOKEN_QUERY, &token), "token query");
  REQUIRE(GetTokenInformation(token, TokenElevation, &elevation, sizeof(elevation), &token_size), "token elevation query");
  REQUIRE(!elevation.TokenIsElevated, "standard token required");
  CloseHandle(token); token = NULL;
  REQUIRE(SetDefaultDllDirectories(LOAD_LIBRARY_SEARCH_SYSTEM32), "system-only default DLL directories");
  module = LoadLibraryExW(argv[1], NULL, LOAD_LIBRARY_SEARCH_DLL_LOAD_DIR | LOAD_LIBRARY_SEARCH_SYSTEM32);
  REQUIRE(module, "restricted IUP load");
  REQUIRE(GetModuleFileNameW(module, loaded, MAX_PATH) > 0 && !_wcsicmp(loaded, argv[1]), "loaded DLL origin");
  RESOLVE(IupOpen); RESOLVE(IupClose); RESOLVE(IupVersion); RESOLVE(IupVersionNumber);
  RESOLVE(IupImageRGBA); RESOLVE(IupLabel); RESOLVE(IupButton); RESOLVE(IupVboxv); RESOLVE(IupDialog);
  RESOLVE(IupSetAttribute); RESOLVE(IupSetStrAttribute); RESOLVE(IupGetAttribute); RESOLVE(IupSetAttributeHandle);
  RESOLVE(IupSetCallback); RESOLVE(IupMap); RESOLVE(IupUnmap); RESOLVE(IupDestroy);
  REQUIRE(pIupVersionNumber() == 330000 && strcmp(pIupVersion(), "3.30") == 0, "IUP version");
  REQUIRE(pIupOpen(NULL, NULL) == IUP_NOERROR, "IupOpen"); opened = 1;
  image = pIupImageRGBA(2, 2, pixels); REQUIRE(image, "RGBA image creation");
  label = pIupLabel(NULL); REQUIRE(label, "label creation");
  button = pIupButton("Inert callback", NULL); REQUIRE(button, "button creation");
  pIupSetAttributeHandle(label, "IMAGE", image);
  pIupSetAttribute(label, "RASTERSIZE", "2x2");
  pIupSetAttribute(label, "ALIGNMENT", "ALEFT:ATOP");
  pIupSetStrAttribute(button, "TITLE", "Attribute roundtrip");
  REQUIRE(strcmp(pIupGetAttribute(button, "TITLE"), "Attribute roundtrip") == 0, "attribute roundtrip");
  pIupSetCallback(button, "ACTION", (Icallback)on_click);
  children[0] = label; children[1] = button; children[2] = NULL;
  box = pIupVboxv(children); REQUIRE(box, "container creation");
  dialog = pIupDialog(box); REQUIRE(dialog, "dialog creation");
  REQUIRE(pIupMap(dialog) == IUP_NOERROR, "hidden mapping"); mapped = 1;
  REQUIRE(!IsWindowVisible((HWND)pIupGetAttribute(dialog, "WID")), "dialog remained hidden");
  label_hwnd = (HWND)pIupGetAttribute(label, "WID");
  button_hwnd = (HWND)pIupGetAttribute(button, "WID");
  REQUIRE(IsWindow(label_hwnd) && IsWindow(button_hwnd), "native control handles");
  SendMessageW(button_hwnd, BM_CLICK, 0, 0);
  REQUIRE(clicks == 1, "inert native callback");

  /* Draw only our hidden image label into a private two-by-two memory bitmap.
     The IUP owner-draw path requests its native image and exercises the DIB bridge. */
  ZeroMemory(&info, sizeof(info));
  info.bmiHeader.biSize = sizeof(BITMAPINFOHEADER);
  info.bmiHeader.biWidth = 2; info.bmiHeader.biHeight = -2;
  info.bmiHeader.biPlanes = 1; info.bmiHeader.biBitCount = 32;
  info.bmiHeader.biCompression = BI_RGB;
  dc = CreateCompatibleDC(NULL); REQUIRE(dc, "memory DC");
  bitmap = CreateDIBSection(dc, &info, DIB_RGB_COLORS, &dib, NULL, 0); REQUIRE(bitmap && dib, "memory DIB");
  previous = SelectObject(dc, bitmap); REQUIRE(previous && previous != HGDI_ERROR, "memory bitmap selection");
  memset(dib, 0, 16);
  ZeroMemory(&draw, sizeof(draw));
  draw.CtlType = ODT_STATIC; draw.CtlID = (UINT)GetDlgCtrlID(label_hwnd);
  draw.itemAction = ODA_DRAWENTIRE; draw.hwndItem = label_hwnd; draw.hDC = dc;
  draw.rcItem.right = 2; draw.rcItem.bottom = 2;
  SendMessageW(GetParent(label_hwnd), WM_DRAWITEM, draw.CtlID, (LPARAM)&draw);
  REQUIRE(GetPixel(dc,0,0) == RGB(255,0,0) && GetPixel(dc,1,0) == RGB(0,255,0)
          && GetPixel(dc,0,1) == RGB(0,0,255) && GetPixel(dc,1,1) == RGB(255,255,255), "RGBA owner-draw pixel roundtrip");
  result = 0;

cleanup:
  if (previous && previous != HGDI_ERROR) SelectObject(dc, previous);
  if (bitmap) DeleteObject(bitmap);
  if (dc) DeleteDC(dc);
  if (dialog && pIupDestroy) { if (mapped) pIupUnmap(dialog); pIupDestroy(dialog); }
  else if (box && pIupDestroy) pIupDestroy(box);
  else if (pIupDestroy) { if (label) pIupDestroy(label); if (button) pIupDestroy(button); }
  if (image && pIupDestroy) pIupDestroy(image);
  if (opened) pIupClose();
  if (module) FreeLibrary(module);
  if (token) CloseHandle(token);
  if (failure) fprintf(stderr, "IUP inert harness failed: %s\n", failure);
  else puts("{\"status\":\"passed\",\"iup_version\":\"3.30\",\"version_number\":330000,\"standard_token\":true,\"restricted_dll_origin_verified\":true,\"hidden_controls_mapped\":true,\"attribute_roundtrip\":true,\"native_callback_count\":1,\"rgba_pixels_verified\":4,\"iup_closed\":true,\"clumsy_executed\":false,\"packet_activity\":false}");
  return result;
}
